//! Generates SIDOU's checked-in C tables in `core/sid/gen/` from reSIDfp (test-only, never
//! linked into firmware). The tables are data derived from reSIDfp, so the generated files
//! carry its licence (GPL-2.0-or-later) and its authors.
//!
//! `cargo run --release -p sidou-tablegen` (from `host/`) rewrites them; the drift test
//! fails when the checked-in files differ from what this produces.

use std::fmt::Write;
use std::path::{Path, PathBuf};

use residfp_sys::{pulldown_table, CombinedWaveforms, Model, PULLDOWN_ROWS};

/// The libresidfp revision the tables come from (the third_party/libresidfp submodule).
pub const RESIDFP_REV: &str = "c1791383";

/// One generated file: its path relative to the repository root, and its contents.
pub struct Generated {
    pub path: &'static str,
    pub contents: String,
}

/// The repository root, from this crate's manifest directory.
pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .canonicalize()
        .expect("repository root")
}

/// Packs 12-bit entries two to three bytes: e0 low 8 bits; e0 high 4 | e1 low 4 << 4;
/// e1 high 8 bits.
fn pack12(row: &[u16; 4096]) -> Vec<u8> {
    row.chunks(2)
        .flat_map(|p| {
            let (a, b) = (p[0], p[1]);
            assert!(a < 0x1000 && b < 0x1000);
            [
                (a & 0xff) as u8,
                ((a >> 8) | ((b & 0x0f) << 4)) as u8,
                (b >> 4) as u8,
            ]
        })
        .collect()
}

/// The combined-waveform strength grid: reSIDfp's three sampled profiles, in order of
/// strength, with the position SIDOU gives each on its 0..1 strength control. AVERAGE,
/// reSIDfp's default, is the middle point. More points (for example by interpolating
/// reSIDfp's model parameters) only lengthen this list: the C layout is indexed by grid
/// point.
pub const STRENGTH_GRID: [(CombinedWaveforms, &str, f32); 3] = [
    (CombinedWaveforms::Weak, "WEAK", 0.0),
    (CombinedWaveforms::Average, "AVERAGE", 0.5),
    (CombinedWaveforms::Strong, "STRONG", 1.0),
];

fn wave_header(model: Model) -> Generated {
    let (name, guard, path, sampled) = match model {
        Model::Mos6581 => (
            "6581",
            "SIDOU_GEN_WAVE_6581_H",
            "core/sid/gen/wave_6581.h",
            "MOS6581",
        ),
        Model::Csg8580 => (
            "8580",
            "SIDOU_GEN_WAVE_8580_H",
            "core/sid/gen/wave_8580.h",
            "CSG8580",
        ),
    };
    let mut s = String::new();
    // REUSE-IgnoreStart
    s.push_str(
        "// SPDX-FileCopyrightText: 2011-2026 Leandro Nini <drfiemost@users.sourceforge.net>\n\
         // SPDX-FileCopyrightText: 2007-2010 Antti Lankila\n\
         // SPDX-License-Identifier: GPL-2.0-or-later\n",
    );
    // REUSE-IgnoreEnd
    let points: Vec<String> = STRENGTH_GRID
        .iter()
        .map(|(_, label, at)| format!("{label} at {at}"))
        .collect();
    writeln!(
        s,
        "/* Generated by sidou-tablegen; do not edit. To regenerate, from host/:\n\
         \x20*   cargo run --release -p sidou-tablegen\n\
         \x20* Source: reSIDfp (libresidfp {RESIDFP_REV}),\n\
         \x20* WaveformCalculator::buildPulldownTable({sampled}, strength): the combined-waveform\n\
         \x20* pulldown, which maps a 12-bit waveform output (the AND of the selected\n\
         \x20* waveforms) to what the chip outputs. One table per point of the strength grid\n\
         \x20* ({}), each with rows in reSIDfp's order: {}.\n\
         \x20* Each row packs 4096 12-bit entries into 6144 bytes, two entries per three\n\
         \x20* bytes; sid_pulldown() in sid_osc.h unpacks them. */",
        points.join(", "),
        PULLDOWN_ROWS.join(", ")
    )
    .unwrap();
    writeln!(
        s,
        "#ifndef {guard}\n#define {guard}\n\n#include <stdint.h>\n"
    )
    .unwrap();
    writeln!(
        s,
        "static const uint8_t SID_PULLDOWN_{name}[{}][5][6144] = {{",
        STRENGTH_GRID.len()
    )
    .unwrap();
    for (cws, label, _) in STRENGTH_GRID {
        let table = pulldown_table(model, cws);
        writeln!(s, "    /* {label} */ {{").unwrap();
        for (row, row_label) in table.iter().zip(PULLDOWN_ROWS) {
            writeln!(s, "        /* {row_label} */ {{").unwrap();
            for line in pack12(row).chunks(14) {
                let bytes: Vec<String> = line.iter().map(|b| format!("0x{b:02x}")).collect();
                writeln!(s, "            {},", bytes.join(", ")).unwrap();
            }
            writeln!(s, "        }},").unwrap();
        }
        writeln!(s, "    }},").unwrap();
    }
    writeln!(s, "}};\n\n#endif").unwrap();
    Generated { path, contents: s }
}

fn grid_header() -> Generated {
    let mut s = String::new();
    // REUSE-IgnoreStart
    s.push_str(
        "// SPDX-FileCopyrightText: 2026 SIDOU contributors\n\
         // SPDX-License-Identifier: GPL-3.0-or-later\n\
         /* Generated by sidou-tablegen; do not edit. The parameter grids of the generated\n\
         \x20* tables: where each grid point sits on its 0..1 control. */\n\
         #ifndef SIDOU_GEN_GRID_H\n#define SIDOU_GEN_GRID_H\n\n",
    );
    // REUSE-IgnoreEnd
    writeln!(
        s,
        "/* Combined-waveform strength: reSIDfp's {} profiles. */",
        STRENGTH_GRID.map(|g| g.1).join(", ")
    )
    .unwrap();
    writeln!(s, "#define SID_STRENGTH_POINTS {}", STRENGTH_GRID.len()).unwrap();
    let at: Vec<String> = STRENGTH_GRID
        .iter()
        .map(|g| format!("{:?}f", g.2))
        .collect();
    writeln!(
        s,
        "static const float SID_STRENGTH_GRID[SID_STRENGTH_POINTS] = {{{}}};",
        at.join(", ")
    )
    .unwrap();
    let default = STRENGTH_GRID
        .iter()
        .position(|g| g.0 == CombinedWaveforms::Average)
        .unwrap();
    writeln!(
        s,
        "#define SID_STRENGTH_DEFAULT {default} /* reSIDfp's AVERAGE */"
    )
    .unwrap();
    writeln!(s, "\n#endif").unwrap();
    Generated {
        path: "core/sid/gen/grid.h",
        contents: s,
    }
}

/// Every generated file.
pub fn generate() -> Vec<Generated> {
    vec![
        grid_header(),
        wave_header(Model::Mos6581),
        wave_header(Model::Csg8580),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pack12_round_trips() {
        let mut row = [0u16; 4096];
        for (i, r) in row.iter_mut().enumerate() {
            *r = ((i * 2654435761) >> 7) as u16 & 0xfff;
        }
        let p = pack12(&row);
        assert_eq!(p.len(), 6144);
        for (i, &v) in row.iter().enumerate() {
            let b = &p[(i / 2) * 3..];
            let got = if i % 2 == 0 {
                u16::from(b[0]) | (u16::from(b[1] & 0x0f) << 8)
            } else {
                u16::from(b[1] >> 4) | (u16::from(b[2]) << 4)
            };
            assert_eq!(got, v, "entry {i}");
        }
    }
}
